const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
const key='zg-demo-requests-v1';
function readStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
function writeStore(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Не удалось сохранить данные. Проверьте настройки браузера.');return false}}
const config=readStore('zg-demo-config',{});
const currentPath=location.pathname.slice(SITE_BASE.length).replace(/\/+$/,'')||'/';
const page=currentPath==='/birthday'?'birthday':currentPath==='/corporate'?'corporate':currentPath==='/admin'?'admin':'home';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Barnaul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const games=[
 {id:'neon',title:'Neon Arena',genre:'Командный шутер',category:'team',age:'12+',players:'2–10 игроков',time:'30–60 мин',image:'hero.webp',position:'77% center',description:'Красная или синяя? Соберите команду, выберите сторону и выйдите на неоновую арену. Перемещайтесь по настоящей площадке, прячьтесь за виртуальными укрытиями и побеждайте вместе.'},
 {id:'zombie',title:'Последний рубеж',genre:'Зомби / Выживание',category:'team',age:'12+',players:'2–8 игроков',time:'30–60 мин',image:'battle.webp',position:'65% center',description:'Город погрузился во тьму. Ваша команда — его последняя надежда. Прикрывайте друг друга, исследуйте локации и выдержите натиск противников. В этом сценарии особенно важна командная работа.'},
 {id:'space',title:'За пределами',genre:'Космическое приключение',category:'adventure',age:'8+',players:'1–6 игроков',time:'30 мин',image:'events.webp',position:'96% center',description:'Окажитесь на далёкой космической станции. Изучайте новый мир, решайте задачи и действуйте сообща. Приключение для тех, кто хочет открыть свою первую виртуальную вселенную.'},
 {id:'kids',title:'Новая реальность',genre:'Для всей семьи',category:'kids',age:'8+',players:'1–6 игроков',time:'30 мин',image:'pattern.webp',position:'center',description:'Начните знакомство с VR с яркого семейного приключения. Понятные правила, спокойный темп и задачи, которые интересно проходить вместе с детьми.'}
];
const faq=[['Никогда не играли в VR. У нас получится?','Да. Перед сеансом инструктор объяснит правила, поможет настроить шлемы и проведёт тренировку. Во время игры он будет рядом и поможет, если возникнут вопросы.'],['Со скольких лет можно играть?','В демонстрационных условиях арены — с 8 лет. Возрастное ограничение зависит от сценария и указано на карточке игры. Для детей выбирайте семейные приключения.'],['Можно прийти одному или вдвоём?','Да. Для одного игрока и пары подойдут приключения; для командных сценариев соберите компанию от двух человек. Выберите число участников в форме записи.'],['Что надеть и что взять с собой?','Подойдёт удобная одежда и закрытая обувь без каблука. Возьмите с собой хорошее настроение и приходите за 15 минут до сеанса, чтобы спокойно пройти инструктаж.'],['Можно принести свой торт и еду?','В тестовом пакете мероприятия предусмотрена лаунж-зона, куда можно принести торт и еду. Перед реальным мероприятием условия необходимо подтвердить у администратора.'],['Что делать, если я ношу очки?','Многие модели шлемов можно использовать с очками. Инструктор поможет проверить посадку. Если есть возможность, для комфорта можно выбрать контактные линзы.']];
const articles=[
 {title:'Первый раз в VR: всё, что нужно знать',category:'Гайд',image:'arena.webp',date:'20 октября 2026',body:'Виртуальная реальность начинается с простых вещей: удобной обуви, настроенного шлема и короткого инструктажа. Приходите заранее — так останется время познакомиться с площадкой и задать вопросы.',sub:'Как проходит первый сеанс',more:'Инструктор подберёт сценарий для вашей компании, расскажет о границах площадки и управлении. После тренировки начнётся игра. Если потребуется пауза, достаточно сообщить об этом инструктору. Новичкам рекомендуем начать с 30 минут.'},
 {title:'День рождения, который станет приключением',category:'Идеи для праздника',image:'events.webp',date:'18 октября 2026',body:'Вместо привычного застолья — командная миссия в другой реальности. На VR-празднике можно объединить игру, дружеский турнир и время для торта в лаунж-зоне.',sub:'Соберите свой сценарий',more:'Выберите дату и количество гостей. Начните с инструктажа, затем устройте несколько раундов с разными командами. После финала оставьте время на общие фотографии, подарки и отдых. Все пакеты и цены на этом сайте демонстрационные.'},
 {title:'Одна команда. Другая реальность.',category:'Командная игра',image:'battle.webp',date:'15 октября 2026',body:'VR меняет привычную обстановку: коллеги оказываются внутри общего приключения и учатся быстро договариваться. Кто-то берёт инициативу, кто-то защищает команду, а кто-то находит неожиданный маршрут.',sub:'Играйте вместе',more:'Для корпоративного события можно выбрать дружеский матч или мини-турнир. Инструктор объяснит правила, сформирует команды и поможет провести раунды. После игры можно обсудить лучшие моменты в лаунж-зоне.'}
];
function brand(){return `<a class="brand" href="/za-granyu-vr-arena/" aria-label="За Гранью — на главную"><img src="/za-granyu-vr-arena/assets/za-granyu-logo-transparent.png" alt="За Гранью — VR-арена" width="2172" height="724"></a>`}
function header(){return `<header class="header"><div class="wrap header-inner">${brand()}<nav class="desktop-nav" aria-label="Главное меню"><a href="/za-granyu-vr-arena/#games">Игры</a><a href="/za-granyu-vr-arena/#events" class="${['birthday','corporate'].includes(page)?'active':''}">Мероприятия</a><a href="/za-granyu-vr-arena/#prices">Цены</a><a href="/za-granyu-vr-arena/#contacts">Контакты</a></nav><div class="header-contact"><a href="tel:+73852000000">+7 (3852) 00-00-00</a><span>Ежедневно · 10:00–22:00</span></div><a class="btn" href="/za-granyu-vr-arena/#booking">Забронировать ${icon('arrow')}</a><a class="icon-btn header-phone" href="tel:+73852000000" aria-label="Позвонить по тестовому номеру">${icon('phone')}</a><button class="icon-btn menu-toggle" aria-label="Открыть меню" aria-expanded="false" data-action="menu">${icon('menu')}</button></div></header><nav class="mobile-nav" aria-label="Мобильное меню"><a href="/za-granyu-vr-arena/#games">Игры</a><a href="/za-granyu-vr-arena/#events">Мероприятия</a><a href="/za-granyu-vr-arena/#prices">Цены</a><a href="/za-granyu-vr-arena/birthday/">Дни рождения</a><a href="/za-granyu-vr-arena/corporate/">Корпоративы</a><a href="/za-granyu-vr-arena/#contacts">Контакты</a><a class="btn" href="/za-granyu-vr-arena/#booking">Забронировать игру ${icon('arrow')}</a><small>Барнаул · Ежедневно 10:00–22:00<br>Демонстрационные контакты</small></nav>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top">${brand()}<nav class="footer-nav" aria-label="Меню внизу страницы"><a href="/za-granyu-vr-arena/#games">Игры</a><a href="/za-granyu-vr-arena/birthday/">Дни рождения</a><a href="/za-granyu-vr-arena/corporate/">Корпоративы</a><a href="/za-granyu-vr-arena/#prices">Цены</a><a href="/za-granyu-vr-arena/#faq">Вопросы и ответы</a></nav><div class="socials"><button aria-label="ВКонтакте — демонстрационная ссылка" data-action="social">VK</button><button aria-label="Telegram — демонстрационная ссылка" data-action="social">TG</button></div></div><div class="footer-bottom"><span>© 2026 «За Гранью». Твой выбор. Твои правила.</span><button data-action="privacy">Политика обработки данных</button><a href="#main" class="backtop">Наверх ${icon('arrow')}</a></div><p class="footer-demo">Демонстрационная версия. Адрес, телефон, цены, игры, отзывы и предложения — тестовые. Формы сохраняют данные только в текущем браузере; отправка писем, внешнее бронирование и Aktivator не подключены. <a href="/za-granyu-vr-arena/admin/">Демо-админка</a>.</p></div></footer>`}
function homeHero(){return `<section class="hero" data-slide="0"><div class="hero-art"${config.home?` style="background-image:url('/za-granyu-vr-arena/assets/${esc(config.home)}')"`:''}></div><div class="wrap hero-inner"><div class="hero-topline"><span>${icon('pin').replace('<svg','<svg style="width:11px;height:11px;display:inline;vertical-align:-2px"')} БАРНАУЛ</span><span>VR-АРЕНА / ЗА ГРАНЬЮ</span></div><div class="eyebrow">Реальность — это только начало</div><h1 id="hero-title">ВЫХОДИ<br>ЗА ГРАНЬ<span>РЕАЛЬНОГО.</span></h1><p class="hero-sub" id="hero-sub">Целый мир по ту сторону шлема. Командные VR-игры со свободой движения и настоящими эмоциями.</p><div class="hero-actions"><a class="btn" href="#booking">Забронировать игру ${icon('arrow')}</a><a class="btn btn-outline" href="#games">Посмотреть игры ${icon('arrow')}</a></div><div class="hero-hud">FREE ROAM<br>ПОЛНАЯ СВОБОДА ДВИЖЕНИЯ</div></div><div class="scroll-cue">SCROLL TO EXPLORE</div><div class="hero-bottom"><div class="wrap"><div class="hero-bottom-inner"><div class="hero-badges"><span>${icon('move')} Без проводов и ограничений</span><span>${icon('users')} Вместе интереснее</span><span>${icon('shield')} Инструктор всегда рядом</span></div><div class="slide-controls"><span class="slide-num"><span id="slide-current">01</span><small>/ 03</small></span><button class="icon-btn" data-action="slide" data-direction="-1" aria-label="Предыдущий слайд">${icon('left')}</button><button class="icon-btn" data-action="slide" data-direction="1" aria-label="Следующий слайд">${icon('arrow')}</button></div></div></div></div></section>`}
function numbers(){return `<div class="numbers"><div class="wrap numbers-inner"><div class="number-item"><strong>200 <span>м²</span></strong><p>пространства<br>для твоей игры</p></div><div class="number-item"><strong>1–10</strong><p>игроков<br>одновременно</p></div><div class="number-item"><strong>8+</strong><p>для детей<br>и взрослых</p></div><div class="number-item">${icon('headset')}<div><strong>Ты внутри игры</strong><p>Полное погружение в другой мир</p></div></div></div></div>`}
function gameCard(g){return `<button class="game-card" data-action="story" data-id="${g.id}" aria-label="Подробнее об игре ${esc(g.title)}"><div class="game-img" style="background-image:url('/za-granyu-vr-arena/assets/${g.image}');background-position:${g.position}${g.id==='zombie'?';filter:hue-rotate(305deg)':''}"></div><div class="game-top"><span class="tag">${g.age} · ${g.category==='team'?'PVP / CO-OP':'ПРИКЛЮЧЕНИЕ'}</span><span class="story-play" aria-hidden="true">▶</span></div><span class="game-genre">${g.genre}</span><h3>${g.title}</h3><div class="game-meta"><span>${g.players}</span><span>${g.time}</span></div><span class="game-arrow">${icon('arrow')}</span></button>`}
function gamesSection(){return `<section class="section games-section" id="games"><div class="wrap"><div class="eyebrow">Выбери свою вселенную</div><div class="section-head"><h2>НЕ ПРОСТО ИГРАЙ.<br><em>БУДЬ В ИГРЕ.</em></h2><p class="games-sub">Сражайся, исследуй и побеждай.<br>У каждой реальности — свой сценарий.</p></div><div class="filters" role="group" aria-label="Категории игр"><button class="filter active" data-filter="all" aria-pressed="true">Все игры</button><button class="filter" data-filter="team" aria-pressed="false">Командные</button><button class="filter" data-filter="adventure" aria-pressed="false">Приключения</button><button class="filter" data-filter="kids" aria-pressed="false">Для детей</button></div><div class="game-grid" id="game-grid">${games.map(gameCard).join('')}</div><div class="game-foot"><span>${icon('info')}Демонстрационный каталог. Поможем выбрать игру по возрасту и настроению.</span><button class="text-link" style="background:none;border-width:0 0 1px" data-action="callback">Помогите выбрать ${icon('arrow')}</button></div></div></section>`}
function experience(){return `<section class="experience"><div class="wrap experience-inner"><div class="experience-visual"><img src="/za-granyu-vr-arena/assets/arena.webp" alt="Концепция арены За Гранью с красной и синей неоновой подсветкой" loading="lazy" width="1536" height="1024"><div class="visual-label">${icon('target')} ТЕРРИТОРИЯ НОВЫХ ВОЗМОЖНОСТЕЙ</div></div><div class="experience-copy"><div class="eyebrow">Больше, чем виртуальность</div><h2>ДВИГАЙСЯ СВОБОДНО.<br>ЧУВСТВУЙ <em>ПО-НАСТОЯЩЕМУ.</em></h2><p>Здесь не нужно сидеть перед экраном. Твоя команда оказывается внутри одной вселенной, где каждое движение имеет значение.</p><div class="feature-list"><div class="feature-row">${icon('move')}<div><b>Целая арена в твоём распоряжении</b><p>Ходи, исследуй и взаимодействуй с миром вокруг.</p></div></div><div class="feature-row">${icon('headset')}<div><b>Максимум погружения</b><p>Беспроводные шлемы и объёмный звук.</p></div></div><div class="feature-row">${icon('users')}<div><b>Одна команда — общая реальность</b><p>Видишь друзей в игре и действуешь вместе с ними.</p></div></div></div><a class="text-link" href="#prices">Найти свой формат ${icon('arrow')}</a></div></div></section>`}
function eventsSection(){return `<section class="section events-section" id="events"><div class="wrap"><div class="eyebrow">Эмоции, которые объединяют</div><div class="section-head"><h2>ТВОЙ ПОВОД.<br><em>НАША РЕАЛЬНОСТЬ.</em></h2><p class="games-sub">Праздники с сюжетом, командой<br>и воспоминаниями за гранью обычного.</p></div><div class="events-grid"><a class="event-card" href="/za-granyu-vr-arena/birthday/"><div class="event-bg"></div><span class="tag">ДЛЯ ДЕТЕЙ И ВЗРОСЛЫХ</span><h3>ДЕНЬ РОЖДЕНИЯ<br>В ДРУГОМ МИРЕ</h3><p>Стань героем своего праздника. Игры, друзья и место для торта.</p><span class="text-link">Собрать свой праздник ${icon('arrow')}</span><span class="event-idx">01</span></a><a class="event-card" href="/za-granyu-vr-arena/corporate/"><div class="event-bg"></div><span class="tag">ДЛЯ ТВОЕЙ КОМАНДЫ</span><h3>КОРПОРАТИВ<br>НА НОВОМ УРОВНЕ</h3><p>Общий вызов вместо рабочего чата. Сражайтесь на одной стороне.</p><span class="text-link">Объединить команду ${icon('arrow')}</span><span class="event-idx">02</span></a></div></div></section>`}
